"""Editorial decisions made during a complete question-by-question semantic reading."""
from sql_semantic_feedback import WINDOW

CHANGES={}
def edit(q,reason,**fields):
    entry=CHANGES.setdefault('sql-foundations-'+q,{'reasons':[]})
    entry['reasons'].append(reason)
    for k,v in fields.items():
        if k in ('choices','wrongs'):entry.setdefault(k,{}).update(v)
        else:entry[k]=v

def why(q,reason,*values):edit(q,reason,wrongOrdered=list(values))

edit('m01-exam-q04','Повтор FK допустим, а не обязателен в каждом текущем наборе.',wrongs={'C':'FK допускает повтор customer_id в разных заказах. Именно это позволяет одному покупателю иметь несколько заказов.'})
edit('m01-exam-q05','Различить товар, позицию и заказ в объяснении кратности.',wrongs={'D':'Один товар может встречаться во многих позициях и заказах; это не связь один-к-одному.'})

edit('m02-l05-q04','В разборе перепутаны % и _.',rationale="В LIKE символ _ соответствует ровно одному символу. Поэтому 'Товар_' задаёт префикс Товар и один дополнительный символ.",wrongs={'A':'Для произвольной подстроки нужен шаблон с % по обеим сторонам.','C':"Для окончания на Товар нужен '%Товар'.",'D':'Подчёркивание требует ещё один символ после Товар: точное Товар не подходит.'})
edit('m02-exam-q01','Пояснение было о FROM вместо полной формы SELECT.',rationale='SELECT product_name, price задаёт два нужных столбца, FROM products — источник. Запрос не изменяет таблицу.',wrongs={'B':'В FROM ошибочно перечислены имена столбцов вместо таблицы products.','C':'В этой форме SQL SELECT должен стоять перед FROM.','D':'Столбцы списка SELECT разделяются запятой; AND связывает логические выражения.'})
edit('m02-l07-q02','Отделить порядок известных дат от положения NULL.',question='**Вопрос:** Как упорядочены строки с датами, не равными NULL, при ORDER BY created_at DESC?',rationale='Известные даты идут от новых к старым. В PostgreSQL DESC по умолчанию ставит NULL раньше известных значений; для другого поведения задают NULLS LAST.')
edit('m02-exam-q23','LIMIT задаёт максимум числа строк, не гарантирует наличие трёх.',question='**Вопрос:** Что делает ORDER BY price DESC LIMIT 3 в PostgreSQL, если price NOT NULL?',choices={'B':'Сортирует по убыванию цены и возвращает не более трёх первых строк.'},rationale='DESC задаёт убывание известных цен, LIMIT 3 ограничивает результат максимум тремя строками; если их меньше, новые строки не создаются.')
edit('m03-l03-q02','В строке SQL нет внутреннего пробела между словами.',rationale="TRIM('  SQL  ') возвращает 'SQL': удалены только пробелы в начале и конце. Внутренние пробелы, если бы они были, сохранились бы.")
for q in ['m03-l04-q02','m03-exam-q17']:
    edit(q,'Уточнить транзакционную семантику текущего времени PostgreSQL.',rationale='В PostgreSQL CURRENT_DATE и CURRENT_TIMESTAMP основаны на времени начала текущей транзакции, с учётом TimeZone при отображении. Для меняющегося текущего момента используется clock_timestamp().')
for q in ['m03-l06-q02','m03-exam-q23']:
    edit(q,'Логический порядок CASE не обещает отсутствие вычисления констант при планировании.',rationale='Поисковый CASE выбирает первую ветвь WHEN с TRUE в порядке записи. Это правило выбора результата, а не гарантия отсутствия любой работы при планировании: например, константное 1/0 может вызвать ошибку до выполнения.')
for q in ['m04-l02-c02','m04-exam-q08']:
    edit(q,'Учитывать функциональную зависимость от PK в PostgreSQL.',question='**Вопрос:** В запросе с GROUP BY не используется исключение PostgreSQL для зависимости от сгруппированного первичного ключа. Какое правило действует для выражений списка SELECT?',rationale='В этой постановке выражение SELECT должно быть сгруппировано или корректно агрегировано. PostgreSQL также разрешает несгруппированные столбцы базовой таблицы, функционально зависящие от её первичного ключа, если весь этот PK входит в GROUP BY.')

DATA_JOIN='Даны orders(order_id): 5001, 5002, 5003, 5004; order_items(order_item_id, order_id): (9001,5001), (9002,5001), (9003,5002), (9004,5003), (9005,5003). Других строк нет.'
for q in ['m05-l02-q03','m05-l07-q03','m05-exam-q21']:
    edit(q,'Встроить фиксированные данные, чтобы ответ не зависел от состояния ShopDB.',question=f'**Вопрос:** {DATA_JOIN} Сколько строк содержит результат orders INNER JOIN order_items ON orders.order_id=order_items.order_id?',rationale='Каждая из пяти позиций ссылается на существующий заказ. Заказ 5004 без позиции исключается. Поэтому JOIN содержит пять строк, COUNT(*)=5.')
edit('m05-l02-c02','Сделать условие отсутствия заказа самодостаточным.',question=f'**Вопрос:** {DATA_JOIN} Почему заказ 5004 отсутствует в результате INNER JOIN orders с order_items?')
edit('m05-l03-q05','Не смешивать количество заказов с количеством результирующих строк.',question=f'**Вопрос:** {DATA_JOIN} Какие заказы будут представлены в результате orders LEFT JOIN order_items по order_id?',rationale='В результате представлены все четыре заказа. Всего результирующих строк шесть: пять позиций плюс строка заказа 5004 с NULL справа.')
edit('m05-l06-q05','Зафиксировать также справочные строки для числового JOIN.',question=f'**Вопрос:** {DATA_JOIN} У каждого заказа есть ровно один существующий покупатель; у каждой позиции ровно один существующий товар. Сколько строк даст цепочка customers → orders → order_items → products через INNER JOIN по соответствующим ключам?')
edit('m05-l06-q04','Следующий INNER JOIN мог бы снова убрать строки без позиций.',choices={'B':'Начать с orders и использовать LEFT JOIN как к order_items, так и далее к products.'},rationale='Вся цепочка должна сохранять отсутствующую правую сторону. Например, orders LEFT JOIN order_items ... LEFT JOIN products ...; INNER JOIN к products после первого LEFT JOIN мог бы убрать заказы без позиций.')
for q in ['m05-l04-q02','m05-exam-q11']:
    edit(q,'При перестановке источников не обещать сохранение позиции столбцов SELECT *.',rationale='A RIGHT JOIN B эквивалентен B LEFT JOIN A по соответствующим именованным полям при том же условии ON. При SELECT * физический порядок выходных столбцов может измениться; для его сохранения задайте явный список SELECT.')

edit('m06-l01-q05','В PostgreSQL 18 псевдоним FROM-подзапроса необязателен.',question='**Вопрос:** Как задать удобное имя производной таблице, полученной подзапросом в FROM PostgreSQL?',rationale='Для удобного обращения можно задать псевдоним: FROM (SELECT ...) AS t. В PostgreSQL 18 его разрешено опускать; обязательным он был в версиях до PostgreSQL 16.')
for q in ['m06-l04-c01','m06-exam-q08']:
    edit(q,'Отличить скалярный IN от сравнения строк с несколькими столбцами.',question='**Вопрос:** Слева от IN стоит одно скалярное значение integer: product_id IN (подзапрос). Сколько столбцов должен возвращать этот подзапрос?',rationale='Скалярный product_id IN (SELECT ...) требует один столбец. Другая форма, (a,b) IN (SELECT x,y ...), сравнивает строки и требует два соответствующих столбца.')
edit('m06-l03-c01','Ноль строк скалярного подзапроса тоже допустим.',choices={'A':'Один столбец и не более одной строки; ноль строк даёт NULL.'},rationale='Скалярный подзапрос имеет один столбец и максимум одну строку. Пустой результат даёт NULL, несколько строк приводят к ошибке.')
edit('m06-l02-q04','ORDER BY должен разрешать ничьи для конкретной выбранной записи.',question='**Вопрос:** Зачем перед LIMIT 1 задавать ORDER BY с уникальным дополнительным ключом, если подзапрос выбирает конкретную запись?',rationale='Полный порядок с уникальным tie-breaker определяет конкретную первую строку. Неуникальная дата сама по себе не разрешает ничью между несколькими записями.')
edit('m06-l03-q05','Убрать скрытую зависимость от дат примера.',question='**Вопрос:** Даны заказы (order_id,created_at): (5001,2026-10-01), (5002,2026-10-02), (5003,2026-10-03), (5004,2026-10-04). Что вернёт SELECT order_id FROM orders WHERE created_at > (SELECT MIN(created_at) FROM orders)?')
CUSTOMERS='Покупатели customers: (101,Анна), (102,Борис), (103,Ирина). В orders есть только customer_id 101,101,102,102; NULL и других строк нет.'
for q in ['m06-l04-q02','m06-l05-q02']:
    edit(q,'Добавить данные и отделить EXISTS от NOT EXISTS.',question=f'**Вопрос:** {CUSTOMERS} Каких покупателей вернёт отбор по '+('customer_id IN (SELECT customer_id FROM orders)?' if '-l04-' in q else 'EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=customers.customer_id)?'),rationale='У Анны (101) и Бориса (102) есть заказы, у Ирины (103) нет. IN и данный коррелированный EXISTS выбирают Анну и Бориса.')
edit('m06-exam-q13','Добавить данные для NOT EXISTS.',question=f'**Вопрос:** {CUSTOMERS} Кто не имеет заказов по NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=customers.customer_id)?',choices={'A':'Ирина (customer_id=103).','B':'Анна (customer_id=101).','C':'Борис (customer_id=102).'},rationale='Только для customer_id=103 подзапрос не находит ни одной строки; NOT EXISTS истинно для Ирины.')
for q in ['m06-l05-q03','m06-l05-q04','m06-l06-q02','m06-l06-q03','m06-l06-q04','m06-l07-q02','m06-l07-q03','m06-l07-q04']:
    explanations={
      'm06-l05-q03':'NOT EXISTS истинен, когда подзапрос не вернул ни одной строки. Значения выбранных столбцов при обычной проверке существования не важны.',
      'm06-l05-q04':'В обычном EXISTS (SELECT 1 FROM ... WHERE ...) проверяется наличие строки, а не значение 1. SELECT 1 сам по себе не ограничивает число найденных строк.',
      'm06-l06-q02':'x > ALL требует TRUE при сравнении x с каждым элементом. Для пустого набора результат TRUE; NULL при отсутствии FALSE может дать UNKNOWN.',
      'm06-l06-q03':'x = ANY (подзапрос) эквивалентно x IN (подзапрос), включая правила обработки NULL.',
      'm06-l06-q04':'Для пустого набора ANY возвращает FALSE: нет ни одного элемента, дающего TRUE.',
      'm06-l07-q02':'UNION ALL объединяет результаты, сохраняя все повторения строк.',
      'm06-l07-q03':'INTERSECT без ALL возвращает общие строки двух результатов, удаляя повторения.',
      'm06-l07-q04':'A EXCEPT B без ALL возвращает различные строки A, отсутствующие в B; порядок результата не гарантируется.'}
    edit(q,'Пояснение было смещено к соседнему вопросу.',rationale=explanations[q])
edit('m06-l05-q01','Проверяется критерий истинности EXISTS, а не частный вид строки.',question='**Вопрос:** Какое необходимое и достаточное условие делает обычный EXISTS(подзапрос) равным TRUE?')
edit('m06-l05-q05','Зафиксировать данные платежей.',question="**Вопрос:** Есть заказы 5001–5004. В payments только (order_id,status): (5001,'succeeded'), (5002,'failed'), (5003,'succeeded'). Какие заказы не имеют успешного платежа?",rationale='У 5001 и 5003 есть succeeded. У 5002 только failed, у 5004 нет платежей; NOT EXISTS успешного платежа выбирает 5002 и 5004.')
for q in ['m06-l06-q05','m06-exam-q20']:
    edit(q,'Зафиксировать цены и категорию в самом условии.',question="**Вопрос:** products содержит только (name,price,category_id): ('Электрочайник',3490,20), ('Кофемолка',4290,20), ('Наушники',5990,30). Какие товары проходят price > "+('ALL' if '-l06-' in q else 'ANY')+' (SELECT price FROM products WHERE category_id=20)?')

edit('m07-l01-q05','Вставка customer_id не обязана быть вставкой заказа.',question='**Вопрос:** Вставляют заказ в orders с customer_id=999, но покупателя 999 в customers нет. Почему INSERT может завершиться ошибкой при немедленно проверяемом FK orders.customer_id?')
edit('m07-l02-q05','Пояснение было о количестве VALUES вместо NOT NULL.',rationale='Нарушение NOT NULL прерывает весь INSERT. Вставки других строк этой же команды откатываются; это не режим автоматического пропуска ошибочной строки.')
edit('m07-l04-q04','Показать предложение RETURNING буквально.',question='**Вопрос:** Что вернёт UPDATE inventory SET quantity=quantity-2 WHERE product_id=303 RETURNING quantity, если строка product_id=303 существует, quantity=20 и ограничений, мешающих изменению, нет?')
edit('m07-exam-q15','В DO UPDATE должен присутствовать conflict target.',question='**Вопрос:** В INSERT ... ON CONFLICT (email) DO UPDATE SET full_name=EXCLUDED.full_name что означает EXCLUDED.full_name?')
edit('m07-exam-q07','Для абсолютной прибавки +10 объяснялась процентная операция.',wrongs={'B':'price + 10 прибавляет десять денежных единиц, а не десять процентов текущей цены.'})

edit('m08-l05-q05','FK не создаёт родительский уникальный индекс.',choices={'C':'На родительской стороне уже должен быть подходящий уникальный ключ или индекс; индекс на дочернем FK-столбце автоматически не создаётся.'},rationale='PRIMARY KEY и UNIQUE создают поддерживающие уникальные индексы при своём объявлении. FOREIGN KEY требует подходящий уже существующий целевой ключ (либо допустимый неполный нечастичный уникальный индекс), а не создаёт его автоматически. Индекс на ссылающихся столбцах добавляют отдельно при необходимости.')
# Correct wording: a suitable full, non-partial index, not a partial index.
CHANGES['sql-foundations-m08-l05-q05']['rationale']=CHANGES['sql-foundations-m08-l05-q05']['rationale'].replace('неполный нечастичный','полный нечастичный')
edit('m08-exam-q09','В исходном вопросе и A, и C являлись необходимыми объектами.',question='**Вопрос:** Таблица orders с customer_id уже создана. Какое требование должно выполняться именно для целевого customers.customer_id перед добавлением обычного внешнего ключа на него?',choices={'A':'На customers.customer_id должен существовать подходящий PRIMARY KEY, UNIQUE или допустимый нечастичный уникальный индекс.'},rationale='Ссылающийся столбец orders.customer_id уже дан. Вопрос о родительском ключе: PostgreSQL должен иметь возможность однозначно проверить ссылку по подходящему уникальному ключу или индексу.',wrongs={'C':'Это ссылающийся столбец orders, который уже существует по условию; вопрос о требовании к целевому ключу customers.'})
edit('m08-exam-q06','Обычный UNIQUE допускает повторные пары с NULL.',question='**Вопрос:** tenant_id и external_id объявлены NOT NULL. Какое ограничение гарантирует уникальность их комбинации, но допускает повторение каждого значения отдельно?',rationale='При NOT NULL составной UNIQUE запрещает повтор пары. Если разрешить NULL, поведение UNIQUE по умолчанию отличается; для приравнивания NULL используют NULLS NOT DISTINCT.')
edit('m08-l06-c01','ALTER TYPE/USING может преобразовать существующие значения.',rationale='ALTER TABLE изменяет определение существующей таблицы. Некоторые формы также преобразуют существующие значения, например ALTER COLUMN TYPE ... USING. Это не команда произвольного изменения строк, аналогичная UPDATE.')
edit('m08-l06-q03','Разбор D не соответствовал варианту про создание FK.',wrongs={'D':'USING при смене типа задаёт преобразование значения, а не создаёт FOREIGN KEY.'})
edit('m08-l03-c01','DEFAULT применяется также в UPDATE SET ...=DEFAULT.',question='**Вопрос:** Когда применяется DEFAULT для обычного столбца при INSERT?')
edit('m08-l04-q01','NOT NULL не запрещает пустую строку и не проверяет формат email.',question='**Вопрос:** Какое объявление гарантирует, что email не равен NULL и его значение не повторяется?',rationale='NOT NULL запрещает NULL, UNIQUE запрещает повтор обычного значения. Они не запрещают пустую строку и не проверяют формат email; эти требования задают отдельно.')
edit('m08-l01-q04','Уточнить выбор схемы и права вместо безусловного public.',rationale='При неквалифицированном CREATE TABLE используется текущая схема, определяемая search_path. Если подходящей схемы нет или отсутствует нужное право CREATE, возникает ошибка; PostgreSQL не обязан переходить к другой доступной для записи схеме.')
edit('m08-l02-q03','Разбор B должен говорить о BY DEFAULT из условия.',wrongs={'B':'В условии BY DEFAULT: явное значение допустимо, если не нарушены другие ограничения. Ограничение явного INSERT характерно для GENERATED ALWAYS.'})

edit('m09-exam-q12','Дистрактор B тоже гарантировал lossless join.',choices={'B':'Общие атрибуты не определяют ни R1, ни R2, но их имена совпадают.'},wrongs={'A':'Отсутствие общих атрибутов само по себе не гарантирует восстановление исходного отношения без ложных комбинаций.','B':'Одного совпадения имён недостаточно; из этого условия не следует требуемая функциональная зависимость.'})
edit('m09-l04-q03','Уточнить учебное правило для одноколоночных ключей.',question='**Вопрос:** Отношение находится в 1NF; все кандидатные ключи одноколоночные. В этой модели нет константных зависимостей ∅ → неключевой атрибут. Что можно заключить?',rationale='В указанных условиях у ключа нет собственного непустого подмножества, а зависимость от пустого множества исключена условием. Поэтому частичных зависимостей неключевых атрибутов нет и выполняется 2NF; 3NF автоматически не следует.')
edit('m09-l05-c02','Пояснение D описывало неверное направление зависимости.',rationale='order_id определяет customer_email транзитивно через customer_id. Это мотивирует хранение email в customers, а не в каждой строке заказа.',wrongs={'D':'payment_id непосредственно определяет order_id; это одна зависимость, а не показанная цепочка через промежуточный customer_id.'})
edit('m09-l04-q01','Задать свойство номера позиции вместо памяти о файле.',question='**Вопрос:** В учебном order_export_raw line_no уникален только внутри заказа, product_id может повторяться в заказе, других кандидатных ключей нет. Какой кандидатный ключ идентифицирует строку?')

edit('m10-l03-c02','При UNION сырой recursive term может возвращать только дубликаты.',choices={'D':'Когда очередной рабочий набор становится пустым, в том числе после удаления уже встречавшихся строк при UNION.'},rationale='Рекурсия завершается при пустом рабочем наборе. При UNION строки, уже встречавшиеся в результате, отбрасываются; поэтому сырой recursive term может вернуть дубликат, но следующего рабочего набора уже не будет.')
edit('m10-l03-q03','Показать anchor и шаг, от которых зависит граница.',question='**Вопрос:** Дан WITH RECURSIVE t(n) AS (VALUES (1) UNION ALL SELECT n+1 FROM t WHERE n<5) SELECT n FROM t. Для чего служит WHERE n<5?')
